Consider the following Python code that processes a large dataset of `(user_id, action)` pairs from a log file:
```python
import sys

def read_log_file(filepath):
    with open(filepath, 'r') as f:
        for line in f:
            user_id, action = line.strip().split(',')
            yield int(user_id), action

def filter_actions(logs, target_action):
    for user_id, action in logs:
        if action == target_action:
            yield user_id

def process_data(filepath, target_action):
    log_generator = read_log_file(filepath)
    filtered_generator = filter_actions(log_generator, target_action)
    return list(filtered_generator)

